class Solution {
  public int shortestDistance(int[][] grid) {
    int m = grid.length, n = grid[0].length, buildings = 0;
    int[][] total = new int[m][n], reached = new int[m][n];
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    int[] queue = new int[m * n];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] != 1) continue;
        buildings++;
        boolean[][] seen = new boolean[m][n];
        int head = 0, tail = 0, steps = 0;
        queue[tail++] = i * n + j;
        seen[i][j] = true;
        while (head < tail) {
          for (int size = tail - head; size > 0; size--) {
            int cell = queue[head++], r = cell / n, c = cell % n;
            if (grid[r][c] == 0) {
              total[r][c] += steps;
              reached[r][c]++;
            }
            for (int d = 0; d < 4; d++) {
              int nr = r + dr[d], nc = c + dc[d];
              if (nr < 0 || nc < 0 || nr >= m || nc >= n || seen[nr][nc] || grid[nr][nc] != 0)
                continue;
              seen[nr][nc] = true;
              queue[tail++] = nr * n + nc;
            }
          }
          steps++;
        }
      }
    }
    int best = Integer.MAX_VALUE;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] == 0 && reached[i][j] == buildings) best = Math.min(best, total[i][j]);
      }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
  }
}
